package com.medtrack.batch.controller; import com.medtrack.batch.dto.*; import com.medtrack.batch.service.BatchService; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/batches") public class BatchController {private final BatchService service;public BatchController(BatchService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('BATCH_READ')") public Page<BatchResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(PageRequest.of(page,Math.min(Math.max(size,1),100)));}@PostMapping @PreAuthorize("hasAuthority('BATCH_CREATE')") public ResponseEntity<BatchResponse> create(@Valid @RequestBody BatchRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('BATCH_READ')") public BatchResponse get(@PathVariable UUID id){return service.get(id);}}
